function getCortexXdrTranslation(key, lang) {
    return (cortexxdrTranslations[lang] && cortexxdrTranslations[lang][key]) ||
           (cortexxdrTranslations.en && cortexxdrTranslations.en[key]) || null;
}

function applyCortexXdrTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.cortex-xdr.") || key.startsWith("review.common."))) {
            const translation = getCortexXdrTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyCortexXdrTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyCortexXdrTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyCortexXdrTranslations(window.i18n?.getCurrentLanguage() || "en");
}
